#include <cstdio>
#include <string>
#include <vector>
#include <queue>
#include <sstream>
#include <iostream>

struct Node {
    int val;
    Node *left, *right;
    Node(int v) : val(v), left(nullptr), right(nullptr) {}
};

void inorder(Node* node, std::vector<int>& out) {
    if (!node) return;
    inorder(node->left, out);
    out.push_back(node->val);
    inorder(node->right, out);
}

int main() {
    std::string line;
    std::getline(std::cin, line);
    std::istringstream iss(line);
    std::vector<std::string> tok;
    std::string t;
    while (iss >> t) tok.push_back(t);
    if (tok.empty() || tok[0] == "null") { printf("\n"); return 0; }

    std::vector<Node*> nodes(tok.size(), nullptr);
    nodes[0] = new Node(std::stoi(tok[0]));
    std::queue<int> q;
    q.push(0);
    size_t i = 1;
    while (!q.empty() && i < tok.size()) {
        int idx = q.front(); q.pop();
        if (i < tok.size()) {
            if (tok[i] != "null") {
                nodes[i] = new Node(std::stoi(tok[i]));
                nodes[idx]->left = nodes[i];
                q.push((int)i);
            }
            ++i;
        }
        if (i < tok.size()) {
            if (tok[i] != "null") {
                nodes[i] = new Node(std::stoi(tok[i]));
                nodes[idx]->right = nodes[i];
                q.push((int)i);
            }
            ++i;
        }
    }
    std::vector<int> out;
    inorder(nodes[0], out);
    for (size_t k = 0; k < out.size(); ++k) {
        if (k) printf(" ");
        printf("%d", out[k]);
    }
    printf("\n");
    return 0;
}
